defmodule SigraInstallGoldenTmpWeb.ReactivationLive do
  @moduledoc """
  LiveView for account reactivation during the deletion grace period.

  Shown when a user whose account is scheduled for deletion logs in.
  Provides options to cancel the deletion and reactivate the account,
  or acknowledge and sign out.

  Generated by `mix sigra.install --live`. Customize freely -- this module
  is owned by your application.
  """
  use SigraInstallGoldenTmpWeb, :live_view
  import SigraInstallGoldenTmpWeb.SigraAuthComponents

  alias SigraInstallGoldenTmp.Accounts, as: Auth

  def mount(_params, _session, socket) do
    user = socket.assigns.current_scope.user

    scheduled_deletion_date =
      if user.scheduled_deletion_at do
        Calendar.strftime(user.scheduled_deletion_at, "%B %d, %Y")
      else
        "unknown"
      end

    {:ok,
     assign(socket,
       page_title: "Account Scheduled for Deletion",
       scheduled_deletion_date: scheduled_deletion_date
     )}
  end

  def render(assigns) do
    ~H"""
    <.sigra_auth_page>
      <div class="sigra-auth-flow sigra-auth-stack sigra-auth-stack--6">
      <.header>
        Your account is scheduled for deletion
      </.header>

      <div class="sigra-auth-notice sigra-auth-notice--warning sigra-auth-stack sigra-auth-stack--4">
        <p>
          Your account is scheduled for deletion on {@scheduled_deletion_date}.
          Finalization will follow the configured deletion strategy.
        </p>
        <p>
          If you'd like to keep your account, you can cancel the deletion now.
        </p>
      </div>

      <div class="sigra-auth-stack sigra-auth-stack--3">
        <.sigra_auth_button phx-click="cancel_deletion" class="sigra-auth-action sigra-auth-action--primary sigra-auth-action--block">
          Cancel deletion and keep my account
        </.sigra_auth_button>
        <.link
          navigate={~p"/users/log_out"}
          class="sigra-auth-action sigra-auth-action--ghost sigra-auth-action--block"
        >
          I understand, sign me out
        </.link>
      </div>
      </div>
    </.sigra_auth_page>
    """
  end

  def handle_event("cancel_deletion", _params, socket) do
    user = socket.assigns.current_scope.user

    case Auth.cancel_deletion(user, scope: socket.assigns.current_scope) do
      {:ok, _user} ->
        {:noreply,
         socket
         |> put_flash(:info, "Account deletion cancelled. Your account is active again.")
         |> push_navigate(to: ~p"/users/settings")}

      {:error, :impersonation_forbidden} ->
        {:noreply,
         put_flash(
           socket,
           :error,
           "You can't change account security settings while impersonating."
         )}

      {:error, _reason} ->
        {:noreply,
         socket
         |> put_flash(:error, "Something went wrong while processing your request. Please try again.")}
    end
  end
end
